CREATE OR REPLACE FUNCTION public.validate_appointment_slot() RETURNS trigger LANGUAGE plpgsql SET search_path = public AS $$ DECLARE cfg public.schedule_settings%ROWTYPE; start_min integer; end_min integer; slot_min integer; last_visit date; BEGIN IF NEW.status = 'cancelado' THEN RETURN NEW; END IF; IF EXTRACT(ISODOW FROM NEW.date) > 5 THEN RAISE EXCEPTION 'O consultório funciona somente de segunda a sexta-feira'; END IF; SELECT * INTO cfg FROM public.schedule_settings WHERE owner_id = NEW.owner_id; start_min := COALESCE(EXTRACT(HOUR FROM cfg.start_time)::integer * 60 + EXTRACT(MINUTE FROM cfg.start_time)::integer, 540); end_min := COALESCE(EXTRACT(HOUR FROM cfg.end_time)::integer * 60 + EXTRACT(MINUTE FROM cfg.end_time)::integer, 1080); slot_min := EXTRACT(HOUR FROM NEW.time)::integer * 60 + EXTRACT(MINUTE FROM NEW.time)::integer; IF slot_min < start_min OR slot_min > end_min OR (slot_min - start_min) % COALESCE(cfg.interval_minutes, 15) <> 0 OR EXTRACT(SECOND FROM NEW.time) <> 0 THEN RAISE EXCEPTION 'Horário fora do funcionamento ou do intervalo de consultas'; END IF; IF TG_OP = 'INSERT' THEN SELECT MAX(date) INTO last_visit FROM public.appointments WHERE owner_id = NEW.owner_id AND patient_id = NEW.patient_id AND status = 'concluído' AND date <= NEW.date; NEW.kind := CASE WHEN last_visit IS NOT NULL AND NEW.date - last_visit <= 30 THEN 'retorno' ELSE 'consulta' END; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_appointment_before_write BEFORE INSERT OR UPDATE OF date,time,status ON public.appointments FOR EACH ROW EXECUTE FUNCTION public.validate_appointment_slot();